### 6. index.html

Coloque em `src/main/resources/static/index.html`.

```html
<!DOCTYPE html>
<html lang="pt-br">
<head>
    <meta charset="UTF-8">
    <title>CRUD Pessoas</title>
</head>
<body>

    <h2>Cadastro de Pessoas</h2>

    <input type="hidden" id="id">

    <input type="text" id="nome" placeholder="Nome da pessoa">

    <button onclick="salvar()">Salvar</button>
    <button onclick="limpar()">Cancelar</button>

    <ul id="lista"></ul>

    <script>

        const API = "/pessoas";

        async function listar() {
            const resposta = await fetch(API);
            const pessoas = await resposta.json();

            const lista = document.getElementById("lista");
            lista.innerHTML = "";

            pessoas.forEach(p => {
                const li = document.createElement("li");

                li.textContent = p.nome + " ";

                const editar = document.createElement("button");
                editar.textContent = "Editar";
                editar.onclick = () => {
                    document.getElementById("id").value = p.id;
                    document.getElementById("nome").value = p.nome;
                };

                const excluir = document.createElement("button");
                excluir.textContent = "Excluir";
                excluir.onclick = () => deletar(p.id);

                li.append(editar, excluir);
                lista.appendChild(li);
            });
        }

        async function salvar() {
            const id = document.getElementById("id").value;
            const nome = document.getElementById("nome").value.trim();

            if (!nome) {
                alert("Digite um nome!");
                return;
            }

            const resposta = await fetch(
                id ? `${API}/${id}` : API,
                {
                    method: id ? "PUT" : "POST",
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify({ nome })
                }
            );

            if (!resposta.ok) {
                alert("Erro ao salvar!");
                return;
            }

            limpar();
            listar();
        }

        async function deletar(id) {
            if (!confirm("Deseja excluir esta pessoa?")) return;

            const resposta = await fetch(`${API}/${id}`, {
                method: "DELETE"
            });

            if (!resposta.ok) {
                alert("Erro ao excluir!");
                return;
            }

            listar();
        }

        function limpar() {
            document.getElementById("id").value = "";
            document.getElementById("nome").value = "";
        }

        listar();

    </script>

</body>
</html>
```

### 7. Como executar

No terminal, dentro da pasta do projeto:

```bash
mvn spring-boot:run
```

Acesse:

`http://localhost:8080`

### 8. Funcionamento

| Operação | Método HTTP | Endpoint |
|---|---|---|
| Listar | GET | /pessoas |
| Cadastrar | POST | /pessoas |
