```java
package com.exemplo.crud;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

@SpringBootApplication
@RestController
@RequestMapping("/pessoas")
public class App {

    private final Map<Long, Pessoa> banco = new ConcurrentHashMap<>();
    private final AtomicLong geradorId = new AtomicLong();

    public static void main(String[] args) {
        SpringApplication.run(App.class, args);
    }

    public record Pessoa(Long id, String nome) {}

    @GetMapping
    public Collection<Pessoa> listar() {
        return banco.values();
    }

    @PostMapping
    public Pessoa criar(@RequestBody Pessoa p) {
        long id = geradorId.incrementAndGet();
        Pessoa nova = new Pessoa(id, p.nome());
        banco.put(id, nova);
        return nova;
    }

    @PutMapping("/{id}")
    public Pessoa atualizar(@PathVariable Long id, @RequestBody Pessoa p) {
        Pessoa atualizada = new Pessoa(id, p.nome());
        banco.put(id, atualizada);
        return atualizada;
    }

    @DeleteMapping("/{id}")
    public void deletar(@PathVariable Long id) {
        banco.remove(id);
    }
}
```

