```java
package com.exemplo.crud;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

@SpringBootApplication
@RestController
@RequestMapping("/pessoas")
public class App {

    private final Map<Long, Pessoa> pessoas = new ConcurrentHashMap<>();
    private final AtomicLong contador = new AtomicLong();

    public static void main(String[] args) {
        SpringApplication.run(App.class, args);
    }

    public record Pessoa(Long id, String nome) {}

    @GetMapping
    public Collection<Pessoa> listar() {
        return pessoas.values();
    }

    @PostMapping
    public Pessoa cadastrar(@RequestBody Pessoa dados) {

        long id = contador.incrementAndGet();

        Pessoa pessoa = new Pessoa(id, dados.nome());

        pessoas.put(id, pessoa);

        return pessoa;
    }

    @PutMapping("/{id}")
    public ResponseEntity<Pessoa> atualizar(
            @PathVariable Long id,
            @RequestBody Pessoa dados) {

        if (!pessoas.containsKey(id)) {
            return ResponseEntity.notFound().build();
        }

        Pessoa pessoa = new Pessoa(id, dados.nome());

        pessoas.put(id, pessoa);

        return ResponseEntity.ok(pessoa);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deletar(@PathVariable Long id) {

        if (pessoas.remove(id) == null) {
            return ResponseEntity.notFound().build();
        }

        return ResponseEntity.noContent().build();
    }
