package com.exemplo.crud;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Collection;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

@SpringBootApplication
@RestController
@RequestMapping("/pessoas")
public class App {

    private final Map<Long, Pessoa> banco = new ConcurrentHashMap<>();
    private final AtomicLong seq = new AtomicLong();

    public static void main(String[] args) {
        SpringApplication.run(App.class, args);
    }

    public record Pessoa(Long id, String nome) {}

    @GetMapping
    public Collection<Pessoa> listar() {
        return banco.values();
    }

    @PostMapping
    public Pessoa criar(@RequestBody Pessoa p) {
        long id = seq.incrementAndGet();
        Pessoa nova = new Pessoa(id, p.nome());
        banco.put(id, nova);
        return nova;
    }

    @PutMapping("/{id}")
    public ResponseEntity<Pessoa> atualizar(@PathVariable Long id, @RequestBody Pessoa dados) {
        Pessoa atualizada = banco.computeIfPresent(id, (k, v) -> new Pessoa(id, dados.nome()));
        return atualizada != null ? ResponseEntity.ok(atualizada) : ResponseEntity.notFound().build();
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deletar(@PathVariable Long id) {
        return banco.remove(id) != null ? ResponseEntity.noContent().build() : ResponseEntity.notFound().build();
    }
}
