```java
package com.exemplo.crud;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Collection;
import java.util.Map;
import java.util.concurrent.ConcurrentSkipListMap;
import java.util.concurrent.atomic.AtomicLong;

@SpringBootApplication
@RestController
@RequestMapping("/pessoas")
public class App {

    public record Pessoa(Long id, String nome) {}

    // ConcurrentSkipListMap mantém a lista ordenada por id
    private final Map<Long, Pessoa> banco = new ConcurrentSkipListMap<>();
    private final AtomicLong proximoId = new AtomicLong();

    public static void main(String[] args) {
        SpringApplication.run(App.class, args);
    }

    @GetMapping
    public Collection<Pessoa> listar() {
        return banco.values();
    }

    @PostMapping
    public Pessoa cadastrar(@RequestBody Pessoa p) {

        long id = proximoId.incrementAndGet();
        Pessoa nova = new Pessoa(id, p.nome());
        banco.put(id, nova);
        return nova;
    }

    @PutMapping("/{id}")
    public ResponseEntity<Pessoa> atualizar(@PathVariable Long id, @RequestBody Pessoa p) {
        if (!banco.containsKey(id)) return ResponseEntity.notFound().build();
        Pessoa atualizada = new Pessoa(id, p.nome());
        banco.put(id, atualizada);
        return ResponseEntity.ok(atualizada);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deletar(@PathVariable Long id) {
        if (banco.remove(id) == null) return ResponseEntity.notFound().build();
        return ResponseEntity.noContent().build();
    }
}
