### `server.js`
```js
// server.js
import express from 'express';
import sqlite3 from 'sqlite3';
import { open } from 'sqlite';
import helmet from 'helmet';
import cors from 'cors';
import morgan from 'morgan';
import { z } from 'zod';

const app = express();
app.use(helmet());
app.use(cors({ origin: 'http://localhost:3000' }));
app.use(morgan('dev'));
app.use(express.json());
app.use(express.static('public'));

let db;
(async () => {
  db = await open({
    filename: './data.db',          // <-- arquivo persistente
    driver: sqlite3.Database,
  });
  await db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      email TEXT NOT NULL UNIQUE
    )
  `);
})();

// ---------- validação ----------
const userSchema = z.object({
  name: z.string().min(1, 'Nome obrigatório'),
  email: z.string().email('E‑mail inválido'),
});

// ---------- rotas ----------
app.get('/users', async (req, res, next) => {
  try {
    const users = await db.all('SELECT * FROM users');
    res.json(users);
  } catch (e) {
    next(e);
  }
});

app.post('/users', async (req, res, next) => {
  try {
    const parsed = userSchema.parse(req.body);
    const result = await db.run(
      'INSERT INTO users (name, email) VALUES (?, ?)',
      [parsed.name, parsed.email]
    );
    res.status(201).json({ id: result.lastID, ...parsed });
  } catch (e) {
    if (e instanceof z.ZodError) {
      return res.status(400).json({ errors: e.errors });
    }
    if (e.code === 'SQLITE_CONSTRAINT') {
      return res.status(409).json({ msg: 'E‑mail já cadastrado' });
    }
    next(e);
  }
});

app.put('/users/:id', async (req, res, next) => {
  try {
    const id = Number(req.params.id);
    const parsed = userSchema.parse(req.body);
    const result = await db.run(
      'UPDATE users SET name = ?, email = ? WHERE id = ?',
      [parsed.name, parsed.email, id]
    );
    if (result.changes === 0) return res.status(404).json({ msg: 'Usuário não encontrado' });
    res.json({ id, ...parsed });
  } catch (e) {
    if (e instanceof z.ZodError) return res.status(400).json({ errors: e.errors });
    if (e.code === 'SQLITE_CONSTRAINT') return res.status(409).json({ msg: 'E‑mail já cadastrado' });
    next(e);
  }
});

app.delete('/users/:id', async (req, res, next) => {
  try {
    const result = await db.run('DELETE FROM users WHERE id = ?', [req.params.id]);
    if (result.changes === 0) return res.status(404).json({ msg: 'Usuário não encontrado' });
    res.json({ success: true });
  } catch (e) {
    next(e);
  }
});

// ---------- middleware de erro ----------
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ msg: 'Erro interno do servidor' });
});

const PORT = 3000;
app.listen(PORT, () => console.log(`🚀 Servidor rodando em http://localhost:${PORT}`));
```

