```java
// Calculadora.java
import java.math.BigDecimal;
import java.math.MathContext;
import java.util.Scanner;

public class Calculadora {

    private static final MathContext MC = MathContext.DECIMAL64;
    private static final Scanner SC = new Scanner(System.in);

    public static void main(String[] args) {
        System.out.println("=== Calculadora Completa ===");
        while (true) {
            System.out.print("\nOperação (+ - * / pow sqrt fact exit): ");
            String op = SC.nextLine().trim().toLowerCase();

            if (op.equals("exit")) break;

            try {
                switch (op) {
                    case "+" -> System.out.println(add(readNumber(), readNumber()));
                    case "-" -> System.out.println(sub(readNumber(), readNumber()));
                    case "*" -> System.out.println(mul(readNumber(), readNumber()));
                    case "/" -> System.out.println(div(readNumber(), readNumber()));
                    case "pow" -> System.out.println(pow(readNumber(), readInt()));
                    case "sqrt" -> System.out.println(sqrt(readNumber()));
                    case "fact" -> System.out.println(factorial(readInt()));
                    default -> System.out.println("Operação desconhecida.");
                }
            } catch (IllegalArgumentException e) {
                System.out.println("Erro: " + e.getMessage());
            }
        }
        SC.close();
    }

    private static BigDecimal readNumber() {
        while (true) {
            System.out.print("Valor: ");
            String txt = SC.nextLine().trim();
            try {
                return new BigDecimal(txt, MC);
            } catch (NumberFormatException e) {
                System.out.println("Entrada inválida. Use número decimal.");
            }
        }
    }

    private static int readInt() {
        while (true) {
            System.out.print("Inteiro: ");
            String txt = SC.nextLine().trim();
            try {
                return Integer.parseInt(txt);
            } catch (NumberFormatException e) {
                System.out.println("Entrada inválida. Use número inteiro.");
            }
        }
    }

    // Operações básicas
    public static BigDecimal add(BigDecimal a, BigDecimal b) { return a.add(b, MC); }
    public static BigDecimal sub(BigDecimal a, BigDecimal b) { return a.subtract(b, MC); }
    public static BigDecimal mul(BigDecimal a, BigDecimal b) { return a.multiply(b, MC); }
    public static BigDecimal div(BigDecimal a, BigDecimal b) {
        if (b.compareTo(BigDecimal.ZERO) == 0)
            throw new IllegalArgumentException("Divisão por zero");
        return a.divide(b, MC);
    }

    // Potência (exponente inteiro)
    public static BigDecimal pow(BigDecimal base, int exp) {
        if (exp < 0) return BigDecimal.ONE.divide(base.pow(-exp), MC);
        return base.pow(exp, MC);
    }

    // Raiz quadrada
    public static BigDecimal sqrt(BigDecimal v) {
        if (v.compareTo(BigDecimal.ZERO) < 0)
            throw new IllegalArgumentException("Raiz de número negativo");
        return new BigDecimal(Math.sqrt(v.doubleValue()), MC);
    }

    // Fatorial (int → BigDecimal)
    public static BigDecimal factorial(int n) {
        if (n < 0) throw new IllegalArgumentException("Fatorial de número negativo");
        BigDecimal result = BigDecimal.ONE;
        for (int i = 2; i <= n; i++) result = result.multiply(BigDecimal.valueOf(i), MC);
        return result;
    }
}
