// CalculadoraCompleta.java
import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.*;

public final class CalculadoraCompleta {

    private static final MathContext MC = new MathContext(34, RoundingMode.HALF_EVEN); // precisão DECIMAL128
    private static final Scanner SC = new Scanner(System.in);
    private final List<String> historico = new ArrayList<>();

    /* ---------- Enum de operações binárias ---------- */
    private enum BinOp {
        SOMA("+", (a, b) -> a.add(b, MC)),
        SUBTRACAO("-", (a, b) -> a.subtract(b, MC)),
        MULTIPLICACAO("*", (a, b) -> a.multiply(b, MC)),
        DIVISAO("/", (a, b) -> {
            if (b.compareTo(BigDecimal.ZERO) == 0)
                throw new ArithmeticException("Divisão por zero");
            // escala automática via MC + arredondamento
            return a.divide(b, MC);
        }),
        POTENCIA("^", (a, b) -> a.pow(b.intValueExact(), MC)),
        MODULO("%", (a, b) -> a.remainder(b, MC));

        final String simbolo;
        final BiFunction<BigDecimal, BigDecimal, BigDecimal> fn;

        BinOp(String s, BiFunction<BigDecimal, BigDecimal, BigDecimal> f) {
            this.simbolo = s;
            this.fn = f;
        }

        static Optional<BinOp> from(String s) {
            return Arrays.stream(values())
                    .filter(o -> o.simbolo.equals(s))
                    .findFirst();
        }
    }

    /* ---------- Enum de operações unárias ---------- */
    private enum UnOp {
        RAIZ("sqrt", a -> {
            if (a.compareTo(BigDecimal.ZERO) < 0)
                throw new ArithmeticException("Raiz de número negativo");
            // Usa BigDecimal via Math.sqrt em double, mas mantemos alta precisão com MC
            double d = Math.sqrt(a.doubleValue());
            return new BigDecimal(d, MC);
        }),
        FATORIAL("fact", a -> {
            if (a.compareTo(BigDecimal.ZERO) < 0 || a.stripTrailingZeros().scale() > 0)
                throw new IllegalArgumentException("Fatorial só para inteiros não‑negativos");
            int n = a.intValueExact();
            BigDecimal res = BigDecimal.ONE;
            for (int i = 2; i <= n; i++) res = res.multiply(BigDecimal.valueOf(i), MC);
            return res;
        });

        final String nome;
        final Function<BigDecimal, BigDecimal> fn;

        UnOp(String n, Function<BigDecimal, BigDecimal> f) {
            this.nome = n;
            this.fn = f;
        }

        static Optional<UnOp> from(String n) {
            return Arrays.stream(values())
                    .filter(o -> o.nome.equalsIgnoreCase(n))
                    .findFirst();
        }
    }

    /* ---------- Métodos auxiliares ---------- */
    private static BigDecimal lerNumero(String msg) {
        while (true) {
            System.out.print(msg);
            if (SC.hasNextBigDecimal()) return SC.nextBigDecimal();
            System.out.println("Entrada inválida. Digite um número válido.");
            SC.next(); // descarta token inválido
        }
    }

    private static String lerLinha() {
        // consome o final de linha deixado por nextX()
        if (SC.hasNextLine()) SC.nextLine();
        System.out.print("> ");
        return SC.nextLine().trim();
    }

    private void registrar(String txt) {
        historico.add(txt);
    }

    /* ---------- Loop principal ---------- */
    public void iniciar() {
        System.out.println("=== CALCULADORA COMPLETA (BigDecimal) ===");
        System.out.println("Operações binárias: + - * / ^ %");
        System.out.println("Operações unárias: sqrt fact");
        System.out.println("Comandos: history | clear | exit");

        while (true) {
            String linha = lerLinha();
            if (linha.isEmpty()) continue;

            if (linha.equalsIgnoreCase("exit")) break;
            if (linha.equalsIgnoreCase("history")) {
                historico.forEach(System.out::println);
                continue;
            }
            if (linha.equalsIgnoreCase("clear")) {
                historico.clear();
                System.out.println("Histórico limpo.");
                continue;
            }

            String[] parts = linha.split("\\s+");
            try {
                if (parts.length == 2) { // unária: <op> <num>
                    UnOp u = UnOp.from(parts[0]).orElseThrow();
                    BigDecimal a = new BigDecimal(parts[1], MC);
                    BigDecimal r = u.fn.apply(a);
                    System.out.println("Resultado: " + r);
                    registrar(String.format("%s %s = %s", u.nome, a, r));
                } else if (parts.length == 3) { // binária: <num> <op> <num>
                    BigDecimal a = new BigDecimal(parts[0], MC);
                    BinOp b = BinOp.from(parts[1]).orElseThrow();
                    BigDecimal c = new BigDecimal(parts[2], MC);
                    BigDecimal r = b.fn.apply(a, c);
                    System.out.println("Resultado: " + r);
                    registrar(String.format("%s %s %s = %s", a, b.simbolo, c, r));
                } else {
                    System.out.println("Formato inválido. Use: <num> <op> <num> ou <op> <num>.");
                }
            } catch (NoSuchElementException | IllegalArgumentException | ArithmeticException e) {
                System.out.println("Erro: " + e.getMessage());
            }
        }
        SC.close();
        System.out.println("Encerrando a calculadora.");
    }

    /* ---------- Main ---------- */
    public static void main(String[] args) {
        new CalculadoraCompleta().iniciar();
    }
}
